// Microsoft Sentinel — auto-derived from the Defender XDR hunt.
// Requires the Microsoft 365 Defender data connector (streams the
// advanced-hunting tables into Sentinel; Timestamp → TimeGenerated).
DeviceNetworkEvents
| where TimeGenerated > ago(7d)
| where InitiatingProcessFileName in~ ("convert","mogrify","identify","composite","montage","conjure","stream","import","magick","gm")
| where RemoteIPType == "Public"
| summarize FirstSeen=min(TimeGenerated), Conns=count(), Ports=make_set(RemotePort,10), Urls=make_set(RemoteUrl,10) by DeviceName, InitiatingProcessFileName, InitiatingProcessCommandLine, RemoteIP
| order by FirstSeen desc

